SELECT *, ROUND(sqft / SUM(sqft) OVER (PARTITION BY city), 4) AS sqft_share, ROUND(sqft / SUM(sqft) OVER (PARTITION BY city), 4) AS sqft_share_2, NTILE(4) OVER (PARTITION BY city ORDER BY sqft, id) AS sqft_bucket, ROW_NUMBER() OVER (PARTITION BY region ORDER BY sqft, id) AS event_seq, FIRST_VALUE(region) IGNORE NULLS OVER (PARTITION BY region ORDER BY sqft, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_region FROM stores
